package com.url_shortener.model; import javax.persistence.Column; import javax.persistence.Entity; import javax.persistence.GeneratedValue; import javax.persistence.GenerationType; import javax.persistence.Id; import javax.persistence.Index; import javax.persistence.Table; import java.time.Instant; @Entity @Table(name = "urls", indexes = { @Index(name = "idx_short_code", columnList = "shortCode", unique = true) }) public class Url { @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id; @Column(nullable = false, length = 2048) private String originalUrl; @Column(nullable = false, unique = true, length = 10) private String shortCode; @Column(nullable = false) private Instant creationDate; @Column private Instant expirationDate; @Column(nullable = false) private Long clickCount; public Url() { } public Url(String originalUrl, String shortCode, Instant creationDate, Instant expirationDate) { this.originalUrl = originalUrl; this.shortCode = shortCode; this.creationDate = creationDate; this.expirationDate = expirationDate; this.clickCount = 0L; } public Long getId() { return id; } public void setId(Long id) { this.id = id; } public String getOriginalUrl() { return originalUrl; } public void setOriginalUrl(String originalUrl) { this.originalUrl = originalUrl; } public String getShortCode() { return shortCode; } public void setShortCode(String shortCode) { this.shortCode = shortCode; } public Instant getCreationDate() { return creationDate; } public void setCreationDate(Instant creationDate) { this.creationDate = creationDate; } public Instant getExpirationDate() { return expirationDate; } public void setExpirationDate(Instant expirationDate) { this.expirationDate = expirationDate; } public Long getClickCount() { return clickCount; } public void setClickCount(Long clickCount) { this.clickCount = clickCount; } @Override public String toString() { return "Url{" + "id=" + id + ", originalUrl='" + originalUrl + '\'' + ", shortCode='" + shortCode + '\'' + ", creationDate=" + creationDate + ", expirationDate=" + expirationDate + ", clickCount=" + clickCount + '}'; } }